public function send_transactional_email( $to_email, $subject, $html_body, array $meta = array() ) {
	// S205: dev allowlist — apsauga nuo realaus laisko realiam zmogui is dev aplinkos.
	if ( $this->is_blocked_by_dev_allowlist( $to_email ) ) {
		$this->log_dev_blocked( $to_email, 'send_transactional_email' );
		return array(
			'ok'             => true,
			'esp_message_id' => '',
			'error'          => '',
			'http_code'      => 0,
			'should_retry'   => false,
			'skipped'        => 'dev_allowlist',
		);
	}

	if ( empty( $this->transactional_token ) ) {
		return array( 'ok' => false, 'error' => 'no_transactional_token' );
	}

	$from_email = isset( $meta['from_email'] ) ? $meta['from_email'] : 'terra@petshop.lt';
	$from_name  = isset( $meta['from_name'] ) ? $meta['from_name'] : 'Petshop.lt';
	$to_name    = isset( $meta['to_name'] ) ? $meta['to_name'] : '';

	$body = array(
		'from'    => array( 'email' => $from_email, 'name' => $from_name ),
		// S308 PATAISA: Sender API reikalauja 'to' kaip OBJEKTO (struct), NE masyvo.
		// Buvo array(array(...)) -> HTTP 422 'field "to" should be struct (got array)'.
		// Empiriskai patvirtinta 2026-07-30: struct -> HTTP 200 + emailId.
		'to'      => array( 'email' => $to_email, 'name' => $to_name ),
		// S327: atsakymo adresas. Sender priima `reply_to` (HTTP 200), bet ar
		// REALIAI iraso i MIME — tikrinama atskirai. Jei ignoruoja — zalos nera.
		// Filtras leidzia keisti/isjungti be kodo redagavimo.
		'reply_to' => apply_filters( 'petshop_email_reply_to',
			array( 'email' => 'uzsakymai@petshop.lt', 'name' => 'Petshop.lt' ),
			$to_email ),
		'subject' => $subject,
		'html'    => $html_body,
	);

	$timeout = (int) apply_filters( 'petshop_esp_send_timeout', self::SEND_TIMEOUT, $to_email );
	$r = $this->request( 'POST', '/message/send', $body, $this->transactional_token, $timeout );

	// S1749 (2026-10-03): timeout ar 5xx NEREISKIA, kad laiskas neisejo — Sender daznai vis tiek issiuncia
	// (10-02: 17 ir 21 kopija). Todel: 'uncertain' = nekartoti automatiskai; kartoti saugu tik kai
	// uzklausa tikrai nepasieke Sender (429 rate limit, cURL 6/7/35 — rysys neuzmegztas).
	$pre = ( ! $r['ok'] && 0 === $r['code'] && preg_match( '/cURL error (6|7|35)\b/', (string) $r['error'] ) );
	return array(
		'ok'           => $r['ok'],
		'esp_message_id' => isset( $r['body']['emailId'] ) ? $r['body']['emailId'] : ( isset( $r['body']['id'] ) ? $r['body']['id'] : '' ),
		'error'        => $r['error'],
		'http_code'    => $r['code'],
		'uncertain'    => ( ! $r['ok'] && ( ( 0 === $r['code'] && ! $pre ) || $r['code'] >= 500 ) ),
		'should_retry' => ( ! $r['ok'] && ( 429 === $r['code'] || $pre ) ),
		'ms'           => isset( $r['ms'] ) ? $r['ms'] : 0,
	);
}

